DROP TRIGGER rm_workspace_inbox_events_no_update;
DROP TRIGGER rm_workspace_inbox_events_no_delete;
ALTER TABLE rm_workspace_inbox_events RENAME TO rm_workspace_inbox_events_v30;
CREATE TABLE rm_workspace_inbox_events (
 id INTEGER PRIMARY KEY,
 source_id TEXT NOT NULL REFERENCES rm_workspace_inbox_sources(source_id),
 event_type TEXT NOT NULL CHECK(event_type IN ('ingested','candidate_resolved','exception_opened','assigned','handoff_completed','reassignment_denied','mail_observed','metadata_reviewed','mail_refused')),
 payload_hash TEXT NOT NULL,
 canonical_payload TEXT NOT NULL,
 actor TEXT NOT NULL,
 created_at TEXT NOT NULL
);
INSERT INTO rm_workspace_inbox_events SELECT * FROM rm_workspace_inbox_events_v30;
DROP TABLE rm_workspace_inbox_events_v30;
CREATE TRIGGER rm_workspace_inbox_events_no_update BEFORE UPDATE ON rm_workspace_inbox_events BEGIN SELECT RAISE(ABORT, 'workspace inbox events are append-only'); END;
CREATE TRIGGER rm_workspace_inbox_events_no_delete BEFORE DELETE ON rm_workspace_inbox_events BEGIN SELECT RAISE(ABORT, 'workspace inbox events are append-only'); END;
ALTER TABLE rm_workspace_inbox_exceptions RENAME TO rm_workspace_inbox_exceptions_v30;
CREATE TABLE rm_workspace_inbox_exceptions (
 source_id TEXT PRIMARY KEY REFERENCES rm_workspace_inbox_sources(source_id),
 code TEXT NOT NULL CHECK(code IN ('INBOX_NO_CANDIDATE','INBOX_AMBIGUOUS_CANDIDATES','INBOX_ASSIGNMENT_CONFLICT','MAIL_INTAKE_MISSING_MESSAGE_ID','MAIL_INTAKE_NO_ATTACHMENT','MAIL_INTAKE_OVERSIZED','MAIL_INTAKE_INVALID_MESSAGE','MAIL_INTAKE_AMBIGUOUS_METADATA')),
 required_action TEXT NOT NULL,
 opened_at TEXT NOT NULL,
 resolved_at TEXT
);
INSERT INTO rm_workspace_inbox_exceptions SELECT * FROM rm_workspace_inbox_exceptions_v30;
DROP TABLE rm_workspace_inbox_exceptions_v30;
